# ============================================================
# OUTPUT 3 | 30G-A
# WALL-TO-WALL INTEGRATED OUTPUT 3 CANDIDATE V1
#
# Applies unchanged:
# - AOI01 B18C calibration
# - feature directions
# - within-family weights
# - family weights
# - F05 amplitude
# - B18E evidence-gated class transition logic
#
# Outputs:
# - INTEGRATED_SCORE_0_100
# - INTEGRATED_CLASS
# - CLASS_DELTA
# - CONTEXT_MODIFIER_SCORE
# - CONTEXT_MODIFIER_COVERAGE
#
# IMPORTANT:
# This is an integrated inspection-priority candidate.
# It is NOT independent field-validated plantation condition.
# ============================================================

import ee
import pandas as pd
import numpy as np
from pathlib import Path
from PIL import Image
from IPython.display import display, FileLink
import urllib.request

print("=" * 120)
print("30G-A | WALL-TO-WALL INTEGRATED OUTPUT 3 CANDIDATE V1")
print("=" * 120)

checkpoint_dir = Path("checkpoints_30F")

output_dir = Path("checkpoints_30G")
output_dir.mkdir(
    parents=True,
    exist_ok=True
)


# ============================================================
# 1. RESTORE FROZEN CALIBRATION
# ============================================================

calibration_df = pd.read_csv(
    checkpoint_dir /
    "30F_B18C_AOI01_WALL_TO_WALL_CALIBRATION_V1.csv"
)

family_weight_df = pd.read_csv(
    checkpoint_dir /
    "30F_B18C_FAMILY_WEIGHTS_V1.csv"
)


print("\nCalibration features :", len(calibration_df))
print("Families             :", len(family_weight_df))


if len(calibration_df) != 8:
    raise ValueError(
        "Expected 8 frozen fusion features."
    )

if len(family_weight_df) != 4:
    raise ValueError(
        "Expected 4 frozen evidence families."
    )


# ============================================================
# 2. FEATURE SOURCE REGISTRY
# ============================================================

feature_source_registry = {

    "LOCAL_RELIEF_300M_M":
        ASSETS["TERRAIN"],

    "SLOPE_DEG":
        ASSETS["TERRAIN"],

    "HAND_M":
        ASSETS["HYDRO"],

    "SILT_PCT_DEEP_100_200CM":
        ASSETS["SOIL"],

    "SOC_GKG_SURFACE_0_30CM":
        ASSETS["SOIL"],

    "WV1500_DEEP_100_200CM":
        ASSETS["SOIL_WATER"],

    "WV10_DEEP_100_200CM":
        ASSETS["SOIL_WATER"],

    "PAW_PROXY_SURFACE_0_30CM":
        ASSETS["SOIL_WATER"]
}


# ============================================================
# 3. CORE
# ============================================================

core_img = ee.Image(
    ASSETS["CORE"]
)

core_class = (
    core_img
    .select("CONDITION_CLASS")
    .round()
    .toInt16()
)

core_raw = (
    core_img
    .select("CONDITION_CLASS_RAW")
    .round()
    .toInt16()
)

core_risk = (
    core_img
    .select("RISK_SCORE_0_100")
    .toFloat()
)


valid_mask = (
    core_class.gte(1)
    .And(
        core_class.lte(4)
    )
)


# ============================================================
# 4. BUILD DIRECTIONAL FEATURE IMAGES
#
# Exactly follows B18C:
#
# P10 -> 0
# P90 -> 1
# clip
# invert negative associations
# [0,1] -> [-1,+1]
# ============================================================

directional_images = {}


for _, row in calibration_df.iterrows():

    feature = row["feature"]

    source = (
        ee.Image(
            feature_source_registry[
                feature
            ]
        )
        .select(feature)
        .toFloat()
        .updateMask(valid_mask)
    )

    p10 = float(row["p10"])
    p90 = float(row["p90"])

    direction = int(
        row[
            "association_direction"
        ]
    )


    norm01 = (
        source
        .subtract(p10)
        .divide(
            p90 - p10
        )
        .clamp(
            0,
            1
        )
    )


    if direction < 0:

        norm01 = (
            ee.Image.constant(1)
            .subtract(norm01)
        )


    directional = (
        norm01
        .multiply(2)
        .subtract(1)
        .rename(
            f"DIR_{feature}"
        )
    )


    directional_images[
        feature
    ] = directional


# ============================================================
# 5. FAMILY COMPOSITES
#
# Replicates available-weight normalization from B18C.
# ============================================================

family_score_images = {}
family_coverage_images = {}


for family in (
    family_weight_df[
        "family"
    ].tolist()
):

    family_cal = calibration_df[
        calibration_df[
            "family"
        ] == family
    ]


    weighted_sum = (
        ee.Image.constant(0)
        .toFloat()
    )

    available_weight = (
        ee.Image.constant(0)
        .toFloat()
    )


    for _, row in family_cal.iterrows():

        feature = row["feature"]

        weight = float(
            row[
                "within_family_weight"
            ]
        )


        img = directional_images[
            feature
        ]


        valid = (
            img.mask()
            .reduce(
                ee.Reducer.min()
            )
            .gt(0)
        )


        weighted_sum = (
            weighted_sum
            .add(
                img
                .unmask(0)
                .multiply(weight)
            )
        )


        available_weight = (
            available_weight
            .add(
                valid
                .toFloat()
                .multiply(weight)
            )
        )


    family_score = (
        weighted_sum
        .divide(
            available_weight
            .max(1e-6)
        )
        .updateMask(
            available_weight.gte(0.50)
        )
        .clamp(
            -1,
            1
        )
        .rename(
            f"FAMILY_SCORE_{family}"
        )
    )


    family_score_images[
        family
    ] = family_score


    family_coverage_images[
        family
    ] = (
        available_weight
        .rename(
            f"FAMILY_COVERAGE_{family}"
        )
    )


# ============================================================
# 6. OVERALL FAMILY-BALANCED MODIFIER
# ============================================================

overall_sum = (
    ee.Image.constant(0)
    .toFloat()
)

overall_weight = (
    ee.Image.constant(0)
    .toFloat()
)


for _, row in family_weight_df.iterrows():

    family = row["family"]

    family_weight = float(
        row["family_weight"]
    )

    img = family_score_images[
        family
    ]


    valid = (
        img.mask()
        .reduce(
            ee.Reducer.min()
        )
        .gt(0)
    )


    overall_sum = (
        overall_sum
        .add(
            img
            .unmask(0)
            .multiply(
                family_weight
            )
        )
    )


    overall_weight = (
        overall_weight
        .add(
            valid
            .toFloat()
            .multiply(
                family_weight
            )
        )
    )


context_modifier = (
    overall_sum
    .divide(
        overall_weight
        .max(1e-6)
    )
    .updateMask(
        overall_weight.gte(0.75)
    )
    .clamp(
        -1,
        1
    )
    .rename(
        "CONTEXT_MODIFIER_SCORE"
    )
)


context_coverage = (
    overall_weight
    .rename(
        "CONTEXT_MODIFIER_COVERAGE"
    )
)


# ============================================================
# 7. F05 INTEGRATED SCORE
#
# Missing context -> adjustment 0
# ============================================================

integrated_score = (

    core_risk

    .add(
        context_modifier
        .unmask(0)
        .multiply(5)
    )

    .clamp(
        0,
        100
    )

    .rename(
        "INTEGRATED_SCORE_0_100"
    )
)


# ============================================================
# 8. CORE EVIDENCE
# ============================================================

optical_valid = (
    core_img
    .select(
        "OPTICAL_VALID_PERIOD_COUNT"
    )
)

alert_mask = (
    core_img
    .select(
        "ALERT_MASK"
    )
    .round()
)

max_period_class = (
    core_img
    .select(
        "MAX_PERIOD_CLASS"
    )
)

max_consecutive = (
    core_img
    .select(
        "MAX_CONSECUTIVE_ALERT"
    )
)


optical_alert_total = (

    core_img.select(
        "GREENNESS_ALERT_PERIODS"
    )

    .add(
        core_img.select(
            "RED_EDGE_ALERT_PERIODS"
        )
    )

    .add(
        core_img.select(
            "MOISTURE_ALERT_PERIODS"
        )
    )
)


has_optical_support = (
    optical_valid.gt(0)
    .And(
        optical_alert_total.gt(0)
    )
)


# preserve existing RAW -> FINAL post-processing
postprocess_lock = (
    core_raw
    .neq(core_class)
)


unlocked = (
    postprocess_lock.Not()
)


# ============================================================
# 9. FROZEN PILOT TRANSITION THRESHOLDS
# ============================================================

T12 = 12
T23 = 22
T34 = 32


# ============================================================
# 10. TRANSITION ELIGIBILITY
# ============================================================

modifier_available = (
    context_modifier
    .mask()
    .reduce(
        ee.Reducer.min()
    )
    .gt(0)
)


modifier_pos = (
    context_modifier
    .unmask(0)
    .gt(0)
)

modifier_neg = (
    context_modifier
    .unmask(0)
    .lt(0)
)


# --------------------------
# 1 -> 2
# --------------------------

promote_1_2 = (
    core_class.eq(1)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_pos)
    .And(integrated_score.gte(T12))
    .And(alert_mask.eq(1))
)


# --------------------------
# 2 -> 3
# --------------------------

promote_2_3 = (
    core_class.eq(2)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_pos)
    .And(integrated_score.gte(T23))
    .And(has_optical_support)
    .And(max_period_class.gte(3))
    .And(max_consecutive.gte(2))
)


# --------------------------
# 3 -> 4
# --------------------------

promote_3_4 = (
    core_class.eq(3)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_pos)
    .And(integrated_score.gte(T34))
    .And(has_optical_support)
    .And(max_period_class.gte(3))
    .And(max_consecutive.gte(3))
)


# --------------------------
# 2 -> 1
# --------------------------

demote_2_1 = (
    core_class.eq(2)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_neg)
    .And(integrated_score.lt(T12))
    .And(alert_mask.eq(0))
)


# --------------------------
# 3 -> 2
# --------------------------

demote_3_2 = (
    core_class.eq(3)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_neg)
    .And(integrated_score.lt(T23))
    .And(max_consecutive.lte(1))
)


# --------------------------
# 4 -> 3
# --------------------------

demote_4_3 = (
    core_class.eq(4)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_neg)
    .And(integrated_score.lt(T34))
    .And(max_consecutive.lte(2))
)


# ============================================================
# 11. APPLY MAXIMUM ±1 CLASS CHANGE
# ============================================================

integrated_class = (
    core_class
    .where(
        promote_1_2,
        2
    )
    .where(
        promote_2_3,
        3
    )
    .where(
        promote_3_4,
        4
    )
    .where(
        demote_2_1,
        1
    )
    .where(
        demote_3_2,
        2
    )
    .where(
        demote_4_3,
        3
    )
    .rename(
        "INTEGRATED_CLASS"
    )
    .toInt16()
)


class_delta = (
    integrated_class
    .subtract(
        core_class
    )
    .rename(
        "CLASS_DELTA"
    )
    .toInt16()
)


# ============================================================
# 12. BUILD FINAL 30G IMAGE
# ============================================================

integrated_img = (

    core_class
    .rename("CORE_CLASS")

    .addBands(
        core_risk
        .rename("CORE_RISK_SCORE_0_100")
    )

    .addBands(
        context_modifier
    )

    .addBands(
        context_coverage
    )

    .addBands(
        integrated_score
    )

    .addBands(
        integrated_class
    )

    .addBands(
        class_delta
    )

    .updateMask(
        valid_mask
    )
)


print(
    "\nIntegrated bands:",
    integrated_img
    .bandNames()
    .getInfo()
)


# ============================================================
# 13. WALL-TO-WALL CLASS TRANSITION AREA
#
# PixelArea at native 10 m core grid.
# ============================================================

transition_code = (
    core_class
    .multiply(10)
    .add(
        integrated_class
    )
    .rename(
        "TRANSITION_CODE"
    )
)


transition_area = (

    ee.Image.pixelArea()
    .divide(10000)        # hectares
    .rename("AREA_HA")
    .addBands(
        transition_code
    )
    .updateMask(
        valid_mask
    )

    .reduceRegion(

        reducer=(
            ee.Reducer.sum()
            .group(
                groupField=1,
                groupName="transition_code"
            )
        ),

        geometry=core_img.geometry(),

        scale=10,

        maxPixels=1e9,

        tileScale=4
    )

    .getInfo()
)


transition_rows = []


for item in transition_area.get(
    "groups",
    []
):

    code = int(
        item[
            "transition_code"
        ]
    )

    old_class = (
        code // 10
    )

    new_class = (
        code % 10
    )


    transition_rows.append({

        "core_class":
            old_class,

        "integrated_class":
            new_class,

        "transition":
            f"{old_class}->{new_class}",

        "area_ha":
            float(
                item["sum"]
            )
    })


transition_area_df = (
    pd.DataFrame(
        transition_rows
    )
    .sort_values(
        [
            "core_class",
            "integrated_class"
        ]
    )
    .reset_index(
        drop=True
    )
)


total_area_ha = (
    transition_area_df[
        "area_ha"
    ].sum()
)


transition_area_df[
    "pct_total_valid_area"
] = (
    transition_area_df[
        "area_ha"
    ]
    /
    total_area_ha
    * 100
)


print("\n" + "=" * 120)
print("WALL-TO-WALL CLASS TRANSITION AREA")
print("=" * 120)

display(
    transition_area_df
)


changed_area_ha = (
    transition_area_df.loc[
        transition_area_df[
            "core_class"
        ]
        !=
        transition_area_df[
            "integrated_class"
        ],
        "area_ha"
    ]
    .sum()
)


changed_area_pct = (
    changed_area_ha
    /
    total_area_ha
    * 100
)


print(
    "\nTotal valid mapped area :",
    round(
        total_area_ha,
        2
    ),
    "ha"
)

print(
    "Changed class area     :",
    round(
        changed_area_ha,
        2
    ),
    "ha"
)

print(
    "Changed class pct      :",
    round(
        changed_area_pct,
        3
    ),
    "%"
)


# ============================================================
# 14. FINAL CLASS AREA
# ============================================================

final_class_area_df = (

    transition_area_df

    .groupby(
        "integrated_class"
    )

    .agg(
        area_ha=(
            "area_ha",
            "sum"
        )
    )

    .reset_index()
)


final_class_area_df[
    "area_pct"
] = (
    final_class_area_df[
        "area_ha"
    ]
    /
    total_area_ha
    * 100
)


print("\n" + "=" * 120)
print("INTEGRATED CLASS AREA")
print("=" * 120)

display(
    final_class_area_df
)


# ============================================================
# 15. GUARDRAIL QA
# ============================================================

max_abs_delta = (

    class_delta
    .abs()

    .reduceRegion(

        reducer=ee.Reducer.max(),

        geometry=core_img.geometry(),

        scale=10,

        maxPixels=1e9,

        tileScale=4
    )

    .get(
        "CLASS_DELTA"
    )

    .getInfo()
)


locked_change_count = (

    postprocess_lock
    .And(
        class_delta.neq(0)
    )

    .rename(
        "LOCKED_CHANGED"
    )

    .reduceRegion(

        reducer=ee.Reducer.sum(),

        geometry=core_img.geometry(),

        scale=10,

        maxPixels=1e9,

        tileScale=4
    )

    .get(
        "LOCKED_CHANGED"
    )

    .getInfo()
)


high_promotion_without_optical = (

    integrated_class
    .gte(3)

    .And(
        integrated_class
        .gt(core_class)
    )

    .And(
        has_optical_support.Not()
    )

    .rename(
        "BAD_HIGH_PROMOTION"
    )

    .reduceRegion(

        reducer=ee.Reducer.sum(),

        geometry=core_img.geometry(),

        scale=10,

        maxPixels=1e9,

        tileScale=4
    )

    .get(
        "BAD_HIGH_PROMOTION"
    )

    .getInfo()
)


checks = {

    "seven_output_bands":
        len(
            integrated_img
            .bandNames()
            .getInfo()
        ) == 7,

    "class_delta_max_abs_1":
        max_abs_delta <= 1,

    "postprocess_lock_preserved":
        locked_change_count == 0,

    "no_high_promotion_without_optical":
        high_promotion_without_optical == 0,

    "valid_transition_area":
        total_area_ha > 0
}


print("\n" + "=" * 120)
print("30G-A | WALL-TO-WALL FINAL GATE")
print("=" * 120)

for name, result in checks.items():

    print(
        f"{name:42s}:",
        "PASS"
        if result
        else "FAIL"
    )


# ============================================================
# 16. VISUALIZATION PNG
# ============================================================

condition_vis = {

    "min": 1,

    "max": 4,

    "palette": [
        "2ca25f",
        "fee08b",
        "f46d43",
        "a50026"
    ],

    "forceRgbOutput":
        True
}


visual = (
    integrated_class
    .updateMask(
        integrated_class.gte(1)
    )
    .visualize(
        **condition_vis
    )
)


outline = (

    ee.Image()
    .byte()

    .paint(

        featureCollection=ee.FeatureCollection([
            ee.Feature(
                core_img.geometry()
            )
        ]),

        color=1,

        width=3
    )

    .selfMask()

    .visualize(
        palette=[
            "000000"
        ],
        forceRgbOutput=True
    )
)


visual = visual.blend(
    outline
)


png_path = (
    output_dir /
    "30G_A_INTEGRATED_CLASS_WALL_TO_WALL_V1.png"
)


thumb_url = visual.getThumbURL({

    "region":
        core_img
        .geometry()
        .bounds(),

    "dimensions":
        1400,

    "format":
        "png"
})


urllib.request.urlretrieve(
    thumb_url,
    png_path
)


print(
    "\nPNG:",
    png_path
)


display(
    Image.open(
        png_path
    )
)


display(
    FileLink(
        str(png_path)
    )
)


# ============================================================
# 17. SAVE QA TABLES
# ============================================================

transition_area_df.to_csv(

    output_dir /
    "30G_A_TRANSITION_AREA_V1.csv",

    index=False
)


final_class_area_df.to_csv(

    output_dir /
    "30G_A_INTEGRATED_CLASS_AREA_V1.csv",

    index=False
)


# ============================================================
# 18. FINAL STATUS
# ============================================================

if all(
    checks.values()
):

    print("""
30G-A = PASS

WALL-TO-WALL INTEGRATED OUTPUT 3 CANDIDATE CREATED.

The final candidate now combines:

1. 30D04 optical/radar core evidence
2. terrain context
3. hydrology context
4. soil context
5. soil-water context
6. bounded F05 environmental modifier
7. evidence-gated Class 1-4 refinement

NEXT MACRO STEPS:

A. Review wall-to-wall transition area and map.

B. Export this exact integrated raster to Earth Engine
   as the AOI01 Integrated Output 3 candidate.

C. Apply the SAME frozen calibration, weights,
   amplitude and transition rules to AOI02.

D. Transferability QC.

E. Web-ready raster / COG / metadata packaging.
""")

else:

    print("""
30G-A requires review.

Do not export the integrated raster yet.
""")

# ============================================================
# ORIGINAL NOTEBOOK CELL 58
# ============================================================

# ============================================================
# OUTPUT 3 | 30G-B
# EXPORT INTEGRATED AOI01 CANDIDATE TO EARTH ENGINE
# ============================================================

import ee

print("=" * 110)
print("30G-B | EXPORT AOI01 INTEGRATED OUTPUT 3")
print("=" * 110)

EXPORT_ASSET = (
    "projects/palm-oil-503202/assets/"
    "SIAK_AOI01_O3_30G_INTEGRATED_V1_2025"
)


# ============================================================
# 1. ADD PROVENANCE METADATA
# ============================================================

export_img = integrated_img.set({

    "OUTPUT":
        "OUTPUT_3",

    "PRODUCT":
        "INTEGRATED_INSPECTION_PRIORITY",

    "VERSION":
        "30G_V1",

    "AOI":
        "SIAK_AOI01",

    "YEAR":
        2025,

    "CORE_SOURCE":
        "SIAK_AOI01_O3_30D04_BALANCED_RISK_2025",

    "FUSION_AMPLITUDE":
        5,

    "TRANSITION_THRESHOLD_1_2":
        12,

    "TRANSITION_THRESHOLD_2_3":
        22,

    "TRANSITION_THRESHOLD_3_4":
        32,

    "MODIFIER_FEATURE_COUNT":
        8,

    "MODIFIER_FAMILY_COUNT":
        4,

    "MODIFIER_FAMILIES":
        "TERRAIN|HYDROLOGY|SOIL|SOIL_WATER",

    "MAX_CLASS_CHANGE":
        1,

    "HIGH_CLASS_REQUIRES_OPTICAL":
        1,

    "AOI01_CALIBRATION_FROZEN":
        1,

    "FIELD_VALIDATED":
        0,

    "INTERPRETATION":
        (
            "Integrated inspection-priority candidate; "
            "not causal diagnosis and not independent "
            "field-validated plantation condition."
        )
})


# ============================================================
# 2. EXPORT
# ============================================================

task = ee.batch.Export.image.toAsset(

    image=export_img,

    description=(
        "SIAK_AOI01_O3_30G_INTEGRATED_V1_2025"
    ),

    assetId=EXPORT_ASSET,

    region=core_img.geometry(),

    scale=10,

    crs="EPSG:32647",

    maxPixels=1e13
)


task.start()


