EXPECTED_CLASS_AREA_HA = {
    1: 9531.973324,
    2: 4079.089398,
    3: 187.304555,
    4: 29.787187,
}

EXPECTED_TOTAL_HA = 13828.154464
EXPECTED_CHANGED_HA = 42.222563

AREA_TOLERANCE_HA = 0.50

# ------------------------------------------------------------
# Initialize Earth Engine
