img = ee.Image(ASSET_ID)

print("=" * 88)
print("30G-C1 | FINAL ASSET STRUCTURAL + NUMERICAL QC")
print("=" * 88)

# ============================================================
# 1. BAND CHECK
# ============================================================

bands = img.bandNames().getInfo()

print("\n[1] BAND STRUCTURE")
print("Band count :", len(bands))

for i, band in enumerate(bands, 1):
    print(f"{i:02d}. {band}")

bands_pass = bands == EXPECTED_BANDS

print("\nExpected exact 7-band structure :", bands_pass)

# ============================================================
# 2. PROJECTION CHECK
# ============================================================

proj = img.select("INTEGRATED_CLASS").projection()

crs = proj.crs().getInfo()
scale = proj.nominalScale().getInfo()

print("\n[2] PROJECTION")
print("CRS           :", crs)
print("Nominal scale :", scale, "m")

projection_pass = (
    crs == "EPSG:32647"
    and abs(float(scale) - 10.0) < 0.01
)

print("Projection QC :", projection_pass)

# ============================================================
# 3. VALUE RANGE CHECK
# ============================================================

region = img.geometry()

qc_bands = img.select([
    "CORE_CLASS",
    "CORE_RISK_SCORE_0_100",
    "CONTEXT_MODIFIER_SCORE",
    "CONTEXT_MODIFIER_COVERAGE",
    "INTEGRATED_SCORE_0_100",
    "INTEGRATED_CLASS",
    "CLASS_DELTA",
])

range_stats = qc_bands.reduceRegion(
    reducer=ee.Reducer.minMax(),
    geometry=region,
    scale=10,
    crs="EPSG:32647",
    maxPixels=1e13,
    tileScale=8
).getInfo()

print("\n[3] VALUE RANGES")

for band in EXPECTED_BANDS:
    min_key = f"{band}_min"
    max_key = f"{band}_max"

    print(
        f"{band:30s}",
        "min =", range_stats.get(min_key),
        "| max =", range_stats.get(max_key)
    )

integrated_class_min = range_stats.get("INTEGRATED_CLASS_min")
integrated_class_max = range_stats.get("INTEGRATED_CLASS_max")

integrated_score_min = range_stats.get("INTEGRATED_SCORE_0_100_min")
integrated_score_max = range_stats.get("INTEGRATED_SCORE_0_100_max")

delta_min = range_stats.get("CLASS_DELTA_min")
delta_max = range_stats.get("CLASS_DELTA_max")

class_range_pass = (
    integrated_class_min is not None
    and integrated_class_max is not None
    and integrated_class_min >= 1
    and integrated_class_max <= 4
)

score_range_pass = (
    integrated_score_min is not None
    and integrated_score_max is not None
    and integrated_score_min >= 0
    and integrated_score_max <= 100
)

delta_pass = (
    delta_min is not None
    and delta_max is not None
    and delta_min >= -1
    and delta_max <= 1
)

print("\nIntegrated Class 1-4 :", class_range_pass)
print("Integrated Score 0-100:", score_range_pass)
print("Class Delta max ±1     :", delta_pass)

# ============================================================
# 4. CLASS AREA CHECK
# ============================================================

class_img = img.select("INTEGRATED_CLASS").toInt16()

area_grouped = (
    ee.Image.pixelArea()
    .divide(10000)
    .rename("AREA_HA")
    .addBands(class_img.rename("CLASS"))
    .reduceRegion(
        reducer=ee.Reducer.sum().group(
            groupField=1,
            groupName="CLASS"
        ),
        geometry=region,
        scale=10,
        crs="EPSG:32647",
        maxPixels=1e13,
        tileScale=8
    )
    .get("groups")
    .getInfo()
)

actual_class_area = {
    int(row["CLASS"]): float(row["sum"])
    for row in area_grouped
}

print("\n[4] INTEGRATED CLASS AREA")

area_pass = True

for cls in [1, 2, 3, 4]:
    actual = actual_class_area.get(cls, 0.0)
    expected = EXPECTED_CLASS_AREA_HA[cls]
    diff = actual - expected

    within_tol = abs(diff) <= AREA_TOLERANCE_HA

    if not within_tol:
        area_pass = False

    print(
        f"Class {cls}: "
        f"{actual:,.6f} ha | "
        f"expected {expected:,.6f} ha | "
        f"diff {diff:+.6f} ha | "
        f"{'PASS' if within_tol else 'CHECK'}"
    )

actual_total_ha = sum(actual_class_area.values())
total_diff = actual_total_ha - EXPECTED_TOTAL_HA

total_pass = abs(total_diff) <= AREA_TOLERANCE_HA

print("\nTotal mapped area :", f"{actual_total_ha:,.6f}", "ha")
print("Expected total    :", f"{EXPECTED_TOTAL_HA:,.6f}", "ha")
print("Difference        :", f"{total_diff:+.6f}", "ha")
print("Total area QC     :", total_pass)

# ============================================================
# 5. CHANGED-CLASS AREA CHECK
# ============================================================

changed_mask = img.select("CLASS_DELTA").neq(0)

changed_area_dict = (
    ee.Image.pixelArea()
    .divide(10000)
    .updateMask(changed_mask)
    .rename("CHANGED_HA")
    .reduceRegion(
        reducer=ee.Reducer.sum(),
        geometry=region,
        scale=10,
        crs="EPSG:32647",
        maxPixels=1e13,
        tileScale=8
    )
    .getInfo()
)

actual_changed_ha = float(
    changed_area_dict.get("CHANGED_HA", 0)
)

changed_diff = actual_changed_ha - EXPECTED_CHANGED_HA

changed_pass = abs(changed_diff) <= AREA_TOLERANCE_HA

print("\n[5] CHANGED CLASS AREA")
print("Actual   :", f"{actual_changed_ha:,.6f}", "ha")
print("Expected :", f"{EXPECTED_CHANGED_HA:,.6f}", "ha")
print("Diff     :", f"{changed_diff:+.6f}", "ha")
print("QC       :", changed_pass)

# ============================================================
# 6. METADATA / PROVENANCE
# ============================================================

property_names = img.propertyNames().getInfo()

print("\n[6] ASSET METADATA / PROVENANCE")
print("Property count:", len(property_names))

for prop in sorted(property_names):
    print("-", prop)

# Print selected metadata safely
metadata = img.toDictionary().getInfo()

print("\nSelected metadata values:")

important_keys = [
    "AOI_ID",
    "YEAR",
    "OUTPUT_ID",
    "PRODUCT",
    "VERSION",
    "CORE_SOURCE",
    "AMPLITUDE",
    "THRESHOLD_12",
    "THRESHOLD_23",
    "THRESHOLD_34",
    "MAX_CLASS_CHANGE",
    "FIELD_VALIDATED",
    "DISCLAIMER",
]

for key in important_keys:
    if key in metadata:
        print(f"{key:22s}: {metadata[key]}")

# ============================================================
# 7. FINAL GATE
# ============================================================

all_pass = all([
    bands_pass,
    projection_pass,
    class_range_pass,
    score_range_pass,
    delta_pass,
    area_pass,
    total_pass,
    changed_pass,
])

print("\n" + "=" * 88)

if all_pass:
    print("30G-C1 RESULT: PASS")
    print("Permanent Output 3 asset matches the frozen 30G-A wall-to-wall result.")
    print("NEXT: 30G-C2 MASK / COVERAGE / EVIDENCE-GUARDRAIL QC.")

else:
    print("30G-C1 RESULT: REVIEW REQUIRED")
    print("Do NOT freeze Output 3 yet.")
    print("Review every CHECK/FALSE result above before continuing.")

print("=" * 88)

